def ensure_minimum(lines: list[str], subject: str) -> list[str]:
    """Add useful, nonblank review assertions until the hard minimum is met."""
    if len(lines) < MIN_LINES:
        add(lines, "## Appendix A. Release-gate assertions", "")
    n = 1
    assertions = (
        "the raw samples and aggregated chart agree",
        "the query result matches the canonical oracle",
        "the engine version and artifact digest are recorded",
        "the selected durability level matches the comparison class",
        "cache state is explicit and reproducible",
        "peak memory includes engine and required sidecars",
        "storage size includes indexes, logs, replicas, and temporary space",
        "timeouts and rejected operations remain in the result set",
        "remote requests and bytes are measured rather than estimated",
        "background maintenance is either quiesced or reported",
        "thread, NUMA, and CPU-affinity settings are captured",
        "the dataset and update-stream digests are immutable",
        "the query plan/profile is archived",
        "unsupported features are not replaced by weaker semantics",
        "a second operator can reproduce the run from a clean host",
    )
    while len(lines) < MIN_LINES:
        assertion = assertions[(n - 1) % len(assertions)]
        add(lines, f"- RG-{n:03d}: For {subject}, release is blocked until {assertion}.")
        n += 1
    return lines


def write_engine(e: Engine) -> None:
    lines = ensure_minimum(engine_lines(e), e.name)
    (ROOT / f"engine-{e.slug}.md").write_text(
        "\n".join(lines).rstrip() + "\n", encoding="utf-8"
    )


